//! DAG (Directed Acyclic Graph) builder for job dependencies

use crate::pipeline::{JobDefinition, PipelineDefinition};
use gitforce_common::{JobId, PipelineRunId, Result};
use std::collections::{HashMap, HashSet};

/// DAG node representing a job
#[derive(Debug, Clone)]
pub struct JobNode {
    pub id: JobId,
    pub name: String,
    pub definition: JobDefinition,
    pub dependencies: Vec<JobId>,
}

/// Job graph representing the pipeline DAG
#[derive(Debug, Clone)]
pub struct JobGraph {
    pub nodes: Vec<JobNode>,
    pub run_id: PipelineRunId,
}

impl JobGraph {
    /// Get nodes with no dependencies (entry points)
    pub fn entry_points(&self) -> Vec<&JobNode> {
        self.nodes
            .iter()
            .filter(|n| n.dependencies.is_empty())
            .collect()
    }

    /// Get a node by ID
    pub fn get(&self, id: JobId) -> Option<&JobNode> {
        self.nodes.iter().find(|n| n.id == id)
    }

    /// Get a node by name
    pub fn get_by_name(&self, name: &str) -> Option<&JobNode> {
        self.nodes.iter().find(|n| n.name == name)
    }

    /// Get nodes that depend on the given node
    pub fn dependents(&self, id: JobId) -> Vec<&JobNode> {
        self.nodes
            .iter()
            .filter(|n| n.dependencies.contains(&id))
            .collect()
    }

    /// Check if the graph has a cycle (invalid DAG)
    pub fn has_cycle(&self) -> bool {
        let mut visited = HashSet::new();
        let mut recursion_stack = HashSet::new();

        for node in &self.nodes {
            if self.detect_cycle_dfs(node.id, &mut visited, &mut recursion_stack) {
                return true;
            }
        }
        false
    }

    fn detect_cycle_dfs(
        &self,
        node_id: JobId,
        visited: &mut HashSet<JobId>,
        recursion_stack: &mut HashSet<JobId>,
    ) -> bool {
        if recursion_stack.contains(&node_id) {
            return true;
        }
        if visited.contains(&node_id) {
            return false;
        }

        visited.insert(node_id);
        recursion_stack.insert(node_id);

        if let Some(node) = self.get(node_id) {
            for dep in &node.dependencies {
                if self.detect_cycle_dfs(*dep, visited, recursion_stack) {
                    return true;
                }
            }
        }

        recursion_stack.remove(&node_id);
        false
    }

    /// Get topological order of nodes
    pub fn topological_order(&self) -> Vec<JobId> {
        let mut result = Vec::new();
        let mut visited = HashSet::new();

        for node in &self.nodes {
            self.visit(node.id, &mut visited, &mut result);
        }

        result
    }

    fn visit(&self, node_id: JobId, visited: &mut HashSet<JobId>, result: &mut Vec<JobId>) {
        if visited.contains(&node_id) {
            return;
        }

        visited.insert(node_id);

        // Visit dependencies first
        if let Some(node) = self.get(node_id) {
            for dep in &node.dependencies {
                self.visit(*dep, visited, result);
            }
        }

        result.push(node_id);
    }
}

/// DAG builder for pipeline jobs
pub struct DagBuilder;

impl DagBuilder {
    /// Build a job graph from a pipeline definition
    pub fn build(
        pipeline: &PipelineDefinition,
        run_id: PipelineRunId,
    ) -> Result<JobGraph> {
        let mut nodes = Vec::new();
        let mut name_to_id = HashMap::new();

        // First pass: create all nodes
        for job in &pipeline.jobs {
            let job_id = JobId::new();
            name_to_id.insert(job.name.clone(), job_id);

            nodes.push(JobNode {
                id: job_id,
                name: job.name.clone(),
                definition: job.clone(),
                dependencies: Vec::new(),
            });
        }

        // Second pass: resolve dependencies
        for node in &mut nodes {
            let dep_ids: Vec<JobId> = node
                .definition
                .needs
                .iter()
                .filter_map(|name| name_to_id.get(name).copied())
                .collect();

            node.dependencies = dep_ids;
        }

        let graph = JobGraph { nodes, run_id };

        // Validate no cycles
        if graph.has_cycle() {
            return Err(gitforce_common::Error::invalid_input(
                "pipeline contains circular dependencies",
            ));
        }

        Ok(graph)
    }

    /// Get the maximum depth of any node in the graph
    pub fn max_depth(graph: &JobGraph) -> usize {
        let mut depths: HashMap<JobId, usize> = HashMap::new();

        for node in &graph.nodes {
            let depth = Self::compute_depth(graph, node.id, &mut depths);
            depths.insert(node.id, depth);
        }

        depths.values().max().copied().unwrap_or(0)
    }

    fn compute_depth(
        graph: &JobGraph,
        node_id: JobId,
        depths: &mut HashMap<JobId, usize>,
    ) -> usize {
        if let Some(&depth) = depths.get(&node_id) {
            return depth;
        }

        let node = match graph.get(node_id) {
            Some(n) => n,
            None => return 0,
        };

        if node.dependencies.is_empty() {
            return 0;
        }

        let max_dep_depth = node
            .dependencies
            .iter()
            .map(|dep| Self::compute_depth(graph, *dep, depths))
            .max()
            .unwrap_or(0);

        max_dep_depth + 1
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::pipeline::StepDefinition;
    use std::collections::HashMap;

    fn make_job(name: &str, needs: Vec<&str>) -> JobDefinition {
        JobDefinition {
            name: name.to_string(),
            image: "rust:latest".to_string(),
            needs: needs.into_iter().map(|s| s.to_string()).collect(),
            env: HashMap::new(),
            steps: vec![StepDefinition {
                name: "step1".to_string(),
                run: "echo hello".to_string(),
                env: None,
                working_directory: None,
                condition: None,
            }],
            timeout: None,
            retry: None,
        }
    }

    #[test]
    fn test_build_simple_dag() {
        let pipeline = PipelineDefinition {
            name: "test".to_string(),
            version: "1.0".to_string(),
            trigger_on: vec![],
            environment: HashMap::new(),
            jobs: vec![make_job("build", vec![]), make_job("test", vec!["build"])],
        };

        let run_id = gitforce_common::PipelineRunId::new();
        let graph = DagBuilder::build(&pipeline, run_id).unwrap();

        assert_eq!(graph.nodes.len(), 2);
        assert!(!graph.has_cycle());

        let build = graph.get_by_name("build").unwrap();
        assert!(build.dependencies.is_empty());

        let test = graph.get_by_name("test").unwrap();
        assert_eq!(test.dependencies.len(), 1);
    }

    #[test]
    fn test_detect_cycle() {
        let jobs = vec![
            make_job("a", vec!["c"]),
            make_job("b", vec!["a"]),
            make_job("c", vec!["b"]), // Creates cycle: a -> c -> b -> a
        ];

        let pipeline = PipelineDefinition {
            name: "test".to_string(),
            version: "1.0".to_string(),
            trigger_on: vec![],
            environment: HashMap::new(),
            jobs,
        };

        let run_id = gitforce_common::PipelineRunId::new();
        let result = DagBuilder::build(&pipeline, run_id);
        // Pipeline with cycle should return error
        assert!(result.is_err());
        let err = result.unwrap_err();
        assert!(err.message.contains("circular"));
    }

    #[test]
    fn test_topological_order() {
        let pipeline = PipelineDefinition {
            name: "test".to_string(),
            version: "1.0".to_string(),
            trigger_on: vec![],
            environment: HashMap::new(),
            jobs: vec![
                make_job("build", vec![]),
                make_job("test", vec!["build"]),
                make_job("deploy", vec!["test"]),
            ],
        };

        let run_id = gitforce_common::PipelineRunId::new();
        let graph = DagBuilder::build(&pipeline, run_id).unwrap();

        let order = graph.topological_order();
        assert_eq!(order.len(), 3);

        // build should come before test, test should come before deploy
        let build_idx = order.iter().position(|id| graph.get(*id).unwrap().name == "build").unwrap();
        let test_idx = order.iter().position(|id| graph.get(*id).unwrap().name == "test").unwrap();
        let deploy_idx = order.iter().position(|id| graph.get(*id).unwrap().name == "deploy").unwrap();

        assert!(build_idx < test_idx);
        assert!(test_idx < deploy_idx);
    }
}

//! CI Engine - orchestrates pipeline execution

use crate::dag::{DagBuilder, JobGraph};
use crate::pipeline::{PipelineDefinition, PipelineTriggerEvent};
use crate::state::JobStateMachine;
use gitforce_common::{JobId, JobStatus, PipelineRunId, PipelineStatus, RepoId, Result};
use std::collections::HashMap;
use std::sync::Arc;
use tokio::sync::RwLock;

/// CI Engine state
#[derive(Debug, Clone)]
pub struct CiEngineState {
    pub run_id: PipelineRunId,
    pub pipeline_id: gitforce_common::PipelineId,
    pub repo_id: RepoId,
    pub status: PipelineStatus,
    pub jobs: HashMap<JobId, JobStateMachine>,
    pub started_at: Option<chrono::DateTime<chrono::Utc>>,
    pub finished_at: Option<chrono::DateTime<chrono::Utc>>,
}

impl CiEngineState {
    pub fn new(
        run_id: PipelineRunId,
        pipeline_id: gitforce_common::PipelineId,
        repo_id: RepoId,
    ) -> Self {
        Self {
            run_id,
            pipeline_id,
            repo_id,
            status: PipelineStatus::Pending,
            jobs: HashMap::new(),
            started_at: None,
            finished_at: None,
        }
    }

    /// Check if all jobs are finished
    pub fn all_jobs_finished(&self) -> bool {
        self.jobs.values().all(|j| j.is_terminal())
    }

    /// Check if all jobs succeeded
    pub fn all_jobs_succeeded(&self) -> bool {
        self.jobs.values().all(|j| j.status() == JobStatus::Succeeded)
    }

    /// Get failed jobs
    pub fn failed_jobs(&self) -> Vec<JobId> {
        self.jobs
            .iter()
            .filter(|(_, j)| j.status() == JobStatus::Failed)
            .map(|(id, _)| *id)
            .collect()
    }

    /// Get pending jobs (not yet started)
    pub fn pending_jobs(&self) -> Vec<JobId> {
        self.jobs
            .iter()
            .filter(|(_, j)| {
                matches!(
                    j.status(),
                    JobStatus::Pending | JobStatus::Queued | JobStatus::Assigned
                )
            })
            .map(|(id, _)| *id)
            .collect()
    }
}

/// CI Engine
pub struct CiEngine {
    state: Arc<RwLock<CiEngineState>>,
    graph: JobGraph,
}

impl CiEngine {
    /// Create a new CI engine from a trigger event and pipeline definition
    pub async fn new(event: PipelineTriggerEvent, pipeline: PipelineDefinition) -> Result<Self> {
        let run_id = PipelineRunId::new();

        // Build DAG from pipeline
        let graph = DagBuilder::build(&pipeline, run_id)?;

        // Create job state machines
        let mut jobs = HashMap::new();
        for node in &graph.nodes {
            jobs.insert(node.id, JobStateMachine::new(node.id));
        }

        let mut state = CiEngineState::new(run_id, event.pipeline_id, event.repo_id);
        state.jobs = jobs;

        Ok(Self {
            state: Arc::new(RwLock::new(state)),
            graph,
        })
    }

    /// Get current engine state
    pub async fn state(&self) -> CiEngineState {
        self.state.read().await.clone()
    }

    /// Start the pipeline run
    pub async fn start(&self) -> Result<()> {
        let mut state = self.state.write().await;
        state.status = PipelineStatus::Running;
        state.started_at = Some(chrono::Utc::now());

        // Queue all entry point jobs
        for node in self.graph.entry_points() {
            if let Some(job_state) = state.jobs.get_mut(&node.id) {
                job_state.queue()?;
            }
        }

        tracing::info!(
            "pipeline {} started with {} jobs",
            state.run_id,
            state.jobs.len()
        );

        Ok(())
    }

    /// Get jobs ready to be scheduled (dependencies satisfied, not yet queued)
    pub async fn ready_jobs(&self) -> Vec<JobId> {
        let state = self.state.read().await;
        let mut ready = Vec::new();

        for node in &self.graph.nodes {
            let job_state = match state.jobs.get(&node.id) {
                Some(s) => s,
                None => continue,
            };

            // Skip if not in queued state
            if job_state.status() != JobStatus::Queued {
                continue;
            }

            // Check if all dependencies are satisfied
            let deps_satisfied = node
                .dependencies
                .iter()
                .all(|dep_id| {
                    state.jobs.get(dep_id).is_some_and(|s| {
                        s.status() == JobStatus::Succeeded
                    })
                });

            if deps_satisfied {
                ready.push(node.id);
            }
        }

        ready
    }

    /// Assign a job to a runner
    pub async fn assign_job(&self, job_id: JobId, runner_id: gitforce_common::RunnerId) -> Result<()> {
        let mut state = self.state.write().await;
        if let Some(job_state) = state.jobs.get_mut(&job_id) {
            job_state.assign(runner_id)?;
        }
        Ok(())
    }

    /// Mark a job as started
    pub async fn start_job(&self, job_id: JobId) -> Result<()> {
        let mut state = self.state.write().await;
        if let Some(job_state) = state.jobs.get_mut(&job_id) {
            job_state.start()?;
        }
        Ok(())
    }

    /// Mark a job as succeeded
    pub async fn succeed_job(&self, job_id: JobId, exit_code: i32) -> Result<()> {
        let mut state = self.state.write().await;
        if let Some(job_state) = state.jobs.get_mut(&job_id) {
            job_state.succeed(exit_code)?;

            // Check if pipeline is complete
            if state.all_jobs_finished() {
                state.status = if state.all_jobs_succeeded() {
                    PipelineStatus::Succeeded
                } else {
                    PipelineStatus::Failed
                };
                state.finished_at = Some(chrono::Utc::now());
            }
        }
        Ok(())
    }

    /// Mark a job as failed
    pub async fn fail_job(&self, job_id: JobId, exit_code: i32, error: String) -> Result<()> {
        let mut state = self.state.write().await;
        if let Some(job_state) = state.jobs.get_mut(&job_id) {
            job_state.fail(exit_code, error)?;

            // Pipeline fails if any job fails
            if !state.failed_jobs().is_empty() {
                state.status = PipelineStatus::Failed;
                state.finished_at = Some(chrono::Utc::now());
            }
        }
        Ok(())
    }

    /// Cancel the pipeline
    pub async fn cancel(&self) -> Result<()> {
        let mut state = self.state.write().await;
        state.status = PipelineStatus::Cancelled;
        state.finished_at = Some(chrono::Utc::now());

        for job_state in state.jobs.values_mut() {
            if !job_state.is_terminal() {
                job_state.cancel().ok();
            }
        }

        Ok(())
    }

    /// Get job info
    pub async fn get_job(&self, job_id: JobId) -> Option<JobStateMachine> {
        let state = self.state.read().await;
        state.jobs.get(&job_id).cloned()
    }

    /// Get the job graph
    pub fn graph(&self) -> &JobGraph {
        &self.graph
    }
}

