        state.queue().unwrap();
        state.assign(RunnerId::new()).unwrap();
        state.start().unwrap();
        state.cancel().unwrap();
        assert_eq!(state.status(), JobStatus::Cancelled);
    }

    #[test]
    fn test_timeout_transition() {
