        let mut state = JobStateMachine::new(job_id);

        state.queue().unwrap();
        state.assign(RunnerId::new()).unwrap();
        state.start().unwrap();
        state.timeout().unwrap();

        assert_eq!(state.status(), JobStatus::TimedOut);
    }

    #[test]
    fn test_runner_id_accessor() {
