//! Result type alias for GitForce
//!
//! Provides a convenient Result type alias using GitForce's Error type.

pub use super::error::Error;

/// Result type alias using GitForce's Error
pub type Result<T> = std::result::Result<T, Error>;

/// Extension trait for Result operations
pub trait ResultExt<T, E> {
    /// Map the error to a different type using a closure
    fn map_err_context<C, F>(self, f: F) -> std::result::Result<T, C>
    where
        F: FnOnce(E) -> C;

    /// Convert to a different error type
    fn context<C>(self, _context: C) -> std::result::Result<T, C>
    where
        E: Into<C>;
}

impl<T, E> ResultExt<T, E> for std::result::Result<T, E> {
    fn map_err_context<C, F>(self, f: F) -> std::result::Result<T, C>
    where
        F: FnOnce(E) -> C,
    {
        self.map_err(f)
    }

    fn context<C>(self, _context: C) -> std::result::Result<T, C>
    where
        E: Into<C>,
    {
        self.map_err(Into::into)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_result_map_err_context() {
        let result: std::result::Result<i32, &str> = Err("original error");
        let mapped = result.map_err_context(|e| format!("wrapped: {}", e));
        assert!(mapped.is_err());
        assert_eq!(mapped.unwrap_err(), "wrapped: original error");
    }

    #[test]
    fn test_result_context() {
        // When E and C are the same type, context doesn't transform the error
        let result: std::result::Result<i32, &str> = Err("error");
        let with_context = result.context("context info");
        assert!(with_context.is_err());
        // E: Into<C> where both are &str just passes through
        assert_eq!(with_context.unwrap_err(), "error");
    }

    #[test]
    fn test_result_context_ok() {
        let result: std::result::Result<i32, &str> = Ok(42);
        let with_context = result.context("context info");
        assert!(with_context.is_ok());
        assert_eq!(with_context.unwrap(), 42);
    }

    #[test]
    fn test_result_map_err_context_ok() {
        let result: std::result::Result<i32, &str> = Ok(100);
        let mapped = result.map_err_context(|e| format!("error: {}", e));
        assert!(mapped.is_ok());
        assert_eq!(mapped.unwrap(), 100);
    }
}

//! Time utilities for GitForce
//!
//! Provides timezone-aware datetime types and utilities.

use chrono::{DateTime as ChronoDateTime, Utc};

/// GitForge's standard timestamp type (UTC)
pub type DateTime = ChronoDateTime<Utc>;

/// Get current UTC timestamp
pub fn now() -> DateTime {
    Utc::now()
}

/// Get current Unix timestamp in milliseconds
pub fn unix_timestamp_ms() -> i64 {
    Utc::now().timestamp_millis()
}

/// Get current Unix timestamp in seconds
pub fn unix_timestamp() -> i64 {
    Utc::now().timestamp()
}

/// Calculate duration between two timestamps in milliseconds
pub fn duration_ms(start: DateTime, end: DateTime) -> i64 {
    (end - start).num_milliseconds()
}

/// Check if a timestamp is older than the given duration
pub fn is_older_than(timestamp: DateTime, duration: chrono::Duration) -> bool {
    Utc::now() - timestamp > duration
}

/// Duration shorthand constructors
pub mod duration {
    use chrono::Duration;

    pub fn seconds(s: i64) -> Duration {
        Duration::seconds(s)
    }

    pub fn minutes(m: i64) -> Duration {
        Duration::minutes(m)
    }

    pub fn hours(h: i64) -> Duration {
        Duration::hours(h)
    }

    pub fn days(d: i64) -> Duration {
        Duration::days(d)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_now() {
        let ts = now();
        assert!(ts <= Utc::now());
    }

    #[test]
    fn test_unix_timestamp() {
        let ts = unix_timestamp();
        assert!(ts > 0);
        assert_eq!(ts, Utc::now().timestamp());
    }

    #[test]
    fn test_unix_timestamp_ms() {
        let ts = unix_timestamp_ms();
        assert!(ts > 0);
    }

    #[test]
    fn test_duration_helpers() {
        assert_eq!(duration::seconds(60), duration::seconds(60));
        assert_eq!(duration::minutes(5), duration::minutes(5));
        assert_eq!(duration::hours(2), duration::hours(2));
        assert_eq!(duration::days(1), duration::days(1));
    }

    #[test]
    fn test_is_older_than() {
        let old = Utc::now() - chrono::Duration::hours(2);
        let recent = Utc::now() - chrono::Duration::minutes(5);

        assert!(is_older_than(old, chrono::Duration::hours(1)));
        assert!(!is_older_than(recent, chrono::Duration::hours(1)));
    }

    #[test]
    fn test_duration_ms() {
        let start = Utc::now();
        let end = start + chrono::Duration::seconds(5);
        assert_eq!(duration_ms(start, end), 5000);
    }

    #[test]
    fn test_duration_helpers_individual() {
        assert_eq!(duration::seconds(30).num_seconds(), 30);
        assert_eq!(duration::minutes(10).num_minutes(), 10);
        assert_eq!(duration::hours(2).num_hours(), 2);
        assert_eq!(duration::days(1).num_days(), 1);
    }

    #[test]
    fn test_duration_comparison() {
        let s1 = duration::seconds(60);
        let m1 = duration::minutes(1);
        let h1 = duration::hours(1);
        let d1 = duration::days(1);

        // All equal
        assert_eq!(s1, m1);
        assert_eq!(m1, chrono::Duration::minutes(1));
        assert_eq!(h1, chrono::Duration::hours(1));
        assert_eq!(d1, chrono::Duration::days(1));
    }

    #[test]
    fn test_is_older_than_edge_cases() {
        let now = Utc::now();
        assert!(is_older_than(now - chrono::Duration::seconds(1), chrono::Duration::seconds(0)));
        assert!(!is_older_than(now, chrono::Duration::days(1)));
    }
}

