    pub fn medium() -> Self {
        Self {
            cpu_ms: 1800000, // 30 minutes
            memory_mb: 2048,
            disk_mb: 5120,
            timeout_secs: 1800,
            network: true,
        }
    }

    pub fn large() -> Self {
        Self {
            cpu_ms: 3600000,
            memory_mb: 8192,
            disk_mb: 20480,
            timeout_secs: 3600,
            network: true,
        }
    }
}

