        sub: user_id.to_string(),
        user_id,
        username: "testuser".to_string(),
        role: "admin".to_string(),
        exp: chrono::Utc::now().timestamp() - 3600, // expired 1 hour ago
        iat: chrono::Utc::now().timestamp() - 7200,
