    let run_id = PipelineRunId::new();
    let graph = DagBuilder::build(&pipeline, run_id).unwrap();

    // Get node by name
    let build = graph.get_by_name("build");
    assert!(build.is_some());
    assert_eq!(build.unwrap().name, "build");

    // Get node by ID
    let build_id = build.unwrap().id;
