    engine.start().await.unwrap();
    {
        let state = engine.state().await;
        assert_eq!(state.status, PipelineStatus::Running);
    }

    // 5. Get ready jobs (build should be ready)
    let ready = engine.ready_jobs().await;
    assert_eq!(ready.len(), 1);

